export const meta = {
  name: 'understand-graphmark',
  description: 'Deep-read every GraphMark subsystem + verify its headline claims against code/results',
  phases: [
    { title: 'Deep-read', detail: 'one reader per subsystem, structured summary' },
    { title: 'Verify', detail: 'check headline quantitative claims against code + results files' },
  ],
}

const GM = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark'
const EG = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/entire-graph'

const READER_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    subsystem: { type: 'string' },
    one_liner: { type: 'string', description: 'single sentence: what this subsystem is' },
    purpose: { type: 'string', description: 'what question it answers / why it exists' },
    how_it_works: { type: 'string', description: 'detailed mechanism: data flow, algorithms, how scoring/building happens, step by step' },
    key_files: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: { path: { type: 'string' }, role: { type: 'string' } },
        required: ['path', 'role'],
      },
    },
    entry_points: { type: 'array', items: { type: 'string' }, description: 'commands / functions to actually run this' },
    gotchas: { type: 'array', items: { type: 'string' }, description: 'fairness controls, biases, known bugs, footguns, non-obvious design choices' },
    load_bearing_claims: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: { claim: { type: 'string' }, evidence_location: { type: 'string' } },
        required: ['claim', 'evidence_location'],
      },
      description: 'quantitative or design claims this subsystem makes, and where the evidence lives',
    },
    open_questions: { type: 'array', items: { type: 'string' } },
  },
  required: ['subsystem', 'one_liner', 'purpose', 'how_it_works', 'key_files'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    claim: { type: 'string' },
    verdict: { type: 'string', enum: ['supported', 'partially-supported', 'unsupported', 'cannot-verify'] },
    evidence: { type: 'string', description: 'exact files/lines/values that back or contradict the claim' },
    notes: { type: 'string' },
  },
  required: ['claim', 'verdict', 'evidence'],
}

const readerBase = `You are deeply reading ONE subsystem of the GraphMark benchmark repo (a compiler-grounded benchmark that scores code-intelligence "brains" — entire-graph/entire-sem vs codebase-memory-mcp vs naive — against a language-compiler oracle). Root: ${GM}. The tool-under-test entire-graph repo is at ${EG}. Read the actual source/config/results files (not just READMEs) — open harness code, oracle code, JSON results, manifests as needed. Be concrete: name functions, flags, env vars, file paths, numbers. Explain the MECHANISM, not just the purpose. Report findings via the structured schema.`

const READERS = [
  { key: 'fidelity-harness', prompt: `${readerBase}

SUBSYSTEM: Fidelity benchmark harness (the Python driver). Read and explain: ${GM}/bench.py, run.py, tasks.py, tasks_endpoint.py, bench_tasks.py, bench_tasks_endpoint.py, diag.py, pytest.ini, and the repos*.json corpus manifests (repos.json, repos-py.json, repos-rust.json, repos-ts.json, repos-heldout.json). Explain end-to-end: how a repo is cloned+pinned, how each system (entire-sem/cbm/naive) is invoked to emit its graph, how precision/recall/F1 are computed vs the oracle, micro vs macro averaging, the difference between bench.py and bench_tasks.py / *_endpoint variants, and how GRAPHMARK_* env vars wire the binaries.` },

  { key: 'go-oracle', prompt: `${readerBase}

SUBSYSTEM: The Go compiler oracle (ground truth ceiling). Read and explain ${GM}/cmd/oracle/main.go fully, plus go.mod/go.sum. Explain the MECHANISM: how it uses go/types to enumerate the true declared symbol inventory (funcs+methods) and the true intra-module static call graph; how (file,line) identity is derived; the "all" vs "exact-only" call sets; the "compiled-file set" fairness control; _test.go symmetric exclusion; the intra-module scope rule; and the fixed rule for excluding repos with incomplete oracle (e.g. ulid). Quote key funcs/structs.` },

  { key: 'lang-oracles', prompt: `${readerBase}

SUBSYSTEM: Per-language oracles beyond Go. Read and explain ${GM}/oracle-py/ (jedi-based oracle.py + requirements), oracle-ts/ (oracle.js, ts-morph + TS checker, package.json), oracle-rust-rustc/ (oracle.py, rustc HIR, Cargo.toml, rust-toolchain.toml), and docs/py-oracle-spike.md, docs/ts-oracle-spike.md, docs/eval-consolidation.md. For EACH language explain how it recovers the symbol inventory + call graph ground truth, what the "oracle_command" contract is (how the harness stays language-agnostic past it), install_deps/node_modules staging for TS, and the known completeness gaps or caveats per language.` },

  { key: 'tasks-suite', prompt: `${readerBase}

SUBSYSTEM: The "Tasks" suite = ${GM}/competitive-eval/ (multi-language fixed-answer + agentic retrieval head-to-head, migrated from entire-plan). Do NOT read the vendored corpus/fixtures. DO read: competitive-eval/README* + results/scoreboard.md, competitive-eval-manifest.json, agentic-cases/ (README, schema.json, token-event-schema.json, AUDIT.json), core-bench/ (README, evaluation-protocol.json, feasibility-report.md, spike-manifest.json), and the product-optimization-v2..v6 dirs (READMEs + success-gates.json + the *freeze*/*burn*/*screening* manifests). Explain: what the Tasks suite measures (retrieval usefulness, not fidelity), what a "task" is and how answers are graded, what the versioned product-optimization-vN sequence is (holdout/burn/screening/freeze protocol, anti-overfitting), and what CORE-Bench is.` },

  { key: 'sweb-harness', prompt: `${readerBase}

SUBSYSTEM: agentic-swebench harness (does the graph help an agent fix real bugs). Read ${GM}/agentic-swebench/README.md then the tools/ scripts: stratify.py, batch_graphs.sh, graph_stats.py, run_matrix.sh, run_pilot.sh, run_cc_one.sh, run_eval_model.sh, score_matrix.py, fair_tokens.py, measure_sweep.py (and any others in tools/). Also tasks/pilot_tasks.json shape. Explain the MECHANISM end-to-end: how the SWE-bench Multilingual pilot is stratified, how per-instance entire-graph dumps are built (bounded <200MB, validated, COMPLETENESS.tsv), what the graph-query tool exposes (def/show/callers/callees/symbols/file/stats), the two agent harnesses (subscription claude -p vs official mini-swe-agent), how patches are captured+scored by the official swebench Docker harness, and how tokens/$ are accounted (whole-pilot vs matched-task collider).` },

  { key: 'sweb-results', prompt: `${readerBase}

SUBSYSTEM: agentic-swebench RESULTS (the actual numbers). Read ${GM}/agentic-swebench/results/matrix_compare.md and walk the results/sonnet/{baseline,treated}/<instance>/ tree — inspect several cc_out.json + patch.diff + problem.txt pairs across languages. Report: which instances exist, the baseline-vs-treated resolved counts and token/$ deltas actually recorded, per-language spread, graph-usage, and whether the README's "pending clean run" caveat is consistent with what's committed. Pull concrete numbers from the JSON, including the recent "sonnet 27/27 resolved, -13% real tokens" claim if present.` },

  { key: 'fidelity-results', prompt: `${readerBase}

SUBSYSTEM: Fidelity RESULTS. Read ${GM}/results/report.md + results.json + tasks.md, results-heldout/, results-py/, results-rust/, results-ts/ (report.md + results.json each). Extract the concrete P/R/F1 numbers per system (entire-sem, cbm, naive) for symbol inventory, call-graph-all, call-graph-exact, micro AND macro, per-repo win/loss tallies, and the exact repo set (and exclusions). Note the four fairness controls as actually applied in the data, and any discrepancy between README-quoted numbers and results.json.` },

  { key: 'entire-graph-subject', prompt: `${readerBase}

SUBSYSTEM: entire-graph itself — the TOOL UNDER TEST (not part of graphmark). Root: ${EG}. Read its README + top-level layout + the command entrypoints (cmd/entire-graph, cmd/entire-sem or equivalent) and the snapshot/graph-export code. Explain: what "entire sem snapshot" and the graph-query interface produce; the graph SCHEMA (node types = symbols; edge types = DEFINES / IMPORTS / CALLS; the fixed 0.62 CALLS confidence; the two Go call-resolution tiers = same-package + unique-method-name; CALLS fan-out cap of 6); how it parses via tree-sitter WITHOUT compiling; and what languages/tiers it supports. This is the subject graphmark measures — explain what capability graphmark is actually probing.` },

  { key: 'tests-audit', prompt: `${readerBase}

SUBSYSTEM: Test + audit discipline. Read ${GM}/tests/ (test_agentic_parity.py, test_core_bench_eval.py, test_core_bench_spike.py, test_core_redaction.py, test_fixes.py) and ${GM}/agentic-swebench/tests/. Also skim recent git log of the repo for the audit story. Explain: what each test guards, the "24 now-fixed harness bugs each with a failing-on-old-code test" claim, the regression gate (ci/regression-gate branch context), the adversarial-audit methodology GraphMark advertises, and redaction/parity checks. Assess how much of the harness's correctness is actually pinned by tests.` },
]

const CLAIMS = [
  { key: 'symbol-f1', claim: 'entire-sem symbol-inventory F1 = 1.000/1.000 (P/R) on both corpus and held-out; CBM trails at ~0.92/0.94 corpus and ~0.98/0.98 held-out.', where: `${GM}/results/results.json, results/report.md, results-heldout/results.json` },
  { key: 'callgraph-f1', claim: 'call-graph (all) F1: entire-sem 0.781 micro / 0.826 macro (corpus) beats CBM 0.618/0.722; entire-sem 0.949/0.954 vs CBM 0.933/0.926 held-out; entire-sem wins 14/17 corpus + 5/7 held-out, 0 held-out losses.', where: `${GM}/results/results.json, results/report.md, results-heldout/` },
  { key: 'testgo-exclusion', claim: '_test.go files are excluded symmetrically from the oracle AND every tool under test (a real fairness bug that was fixed).', where: `${GM}/cmd/oracle/main.go and the harness (run.py/tasks.py); grep for _test.go / test file filtering` },
  { key: 'perlookup-283x', claim: 'Isolated per-lookup: answering the 5 structural questions for a well-connected symbol costs ~2.3k tokens from the graph vs ~654k reading referencing files (~283x).', where: `${GM}/agentic-swebench/tools/measure_sweep.py and any committed measurement output` },
  { key: 'audit-24bugs', claim: 'The agentic-swebench pre-audit pilot numbers were discarded; 24 harness bugs were found+fixed, each with a test that fails on the old code; results are "pending an approved clean run".', where: `${GM}/agentic-swebench/README.md, agentic-swebench/tests/, git log` },
  { key: 'calls-062-cap6', claim: "entire-graph's CALLS edges are a fixed-confidence 0.62 name-collision heuristic (not resolved), and CALLS fan-out is capped at 6 per symbol per direction.", where: `${GM}/agentic-swebench/tools/ (graph build/query) and ${EG} source (call resolution + confidence + cap)` },
  { key: 'sonnet-2727', claim: 'Recent commit (#42) retains a sonnet pilot showing 27/27 resolved and -13% real tokens with +graph (treated) vs baseline.', where: `${GM}/agentic-swebench/results/sonnet/ + matrix_compare.md; git show for the commit` },
]

phase('Deep-read')
const readerThunks = READERS.map((r) => () =>
  agent(r.prompt, { label: `read:${r.key}`, phase: 'Deep-read', schema: READER_SCHEMA }).then((v) => ({ key: r.key, ...(v || {}) }))
)

const verifyThunks = CLAIMS.map((c) => () =>
  agent(
    `Adversarially VERIFY this GraphMark claim against the actual repo. Do not trust the README — open the code/JSON/results files and check the real values. Root: ${GM}, tool-under-test: ${EG}.\n\nCLAIM: ${c.claim}\nWHERE TO LOOK: ${c.where}\n\nReturn verdict + the exact evidence (file paths, values, line references) that supports or contradicts it. If the number in the claim differs from what the files say, report the file's number.`,
    { label: `verify:${c.key}`, phase: 'Verify', schema: VERIFY_SCHEMA }
  ).then((v) => ({ key: c.key, ...(v || {}) }))
)

// Readers + hardcoded-claim verifiers are independent — run in one barrier, phase-tagged.
const all = await parallel([...readerThunks, ...verifyThunks])
const readers = all.slice(0, READERS.length).filter(Boolean)
const verifications = all.slice(READERS.length).filter(Boolean)

return { readers, verifications }

