=== top-level funcs/types ===
27:type Symbol struct {
34:type Edge struct {
43:type Output struct {
61:func main() {
218:func fatal(err error) {

1	// Command oracle emits compiler-grade ground truth for a Go module: the true
2	// set of declared functions/methods and the true static call graph, resolved
3	// through go/types. This is the tool-independent reference a benchmark scores
4	// code-intelligence "brains" (entire-sem, CBM, ...) against — neither tool's
5	// own schema is the rubric, the compiler is.
6	//
7	// Usage: oracle <module-dir>   (prints JSON to stdout)
8	//
9	// Identity is (file, line) of a declaration, which every tree-sitter tool and
10	// the compiler agree on because they parse the same bytes. Scope is intra-module
11	// only (callees resolved to a declaration inside the loaded packages), which is
12	// exactly the scope a local repo brain can know.
13	package main
14	
15	import (
16		"encoding/json"
17		"fmt"
18		"go/ast"
19		"go/types"
20		"os"
21		"path/filepath"
22		"sort"
23	
24		"golang.org/x/tools/go/packages"
25	)
26	
27	type Symbol struct {
28		File string `json:"file"`
29		Line int    `json:"line"`
30		Name string `json:"name"`
31		Kind string `json:"kind"` // function | method
32	}
33	
34	type Edge struct {
35		FromFile string `json:"from_file"`
36		FromLine int    `json:"from_line"`
37		FromName string `json:"from_name"`
38		ToFile   string `json:"to_file"`
39		ToLine   int    `json:"to_line"`
40		ToName   string `json:"to_name"`
41	}
42	
43	type Output struct {
44		Repo string `json:"repo"`
45		// CompiledFiles is the set of source files the compiler actually built for
46		// this build configuration (build-tag-filtered). Tools see every file on
47		// disk; scoring outside this set would unfairly penalize a tool for code the
48		// single-build oracle never compiled, so the harness restricts to it.
49		CompiledFiles []string `json:"compiled_files"`
50		Symbols       []Symbol `json:"symbols"`
51		Calls         []Edge   `json:"calls"`
52		NaiveCalls    []Edge   `json:"naive_calls"`
53		Stats         struct {
54			Packages int `json:"packages"`
55			Symbols  int `json:"symbols"`
56			Calls    int `json:"calls"`
57			LoadErrs int `json:"load_errors"`
58		} `json:"stats"`
59	}
60	
61	func main() {
62		if len(os.Args) < 2 {
63			fmt.Fprintln(os.Stderr, "usage: oracle <module-dir>")
64			os.Exit(2)
65		}
66		dir := os.Args[1]
67		absDir, err := filepath.Abs(dir)
68		if err != nil {
69			fatal(err)
70		}
71	
72		cfg := &packages.Config{
73			Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
74				packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo |
75				packages.NeedDeps | packages.NeedImports,
76			Dir:   absDir,
77			Tests: false,
78		}
79		pkgs, err := packages.Load(cfg, "./...")
80		if err != nil {
81			fatal(err)
82		}
83	
84		out := Output{Repo: absDir}
85		rel := func(p string) string {
86			r, err := filepath.Rel(absDir, p)
87			if err != nil {
88				return filepath.ToSlash(p)
89			}
90			return filepath.ToSlash(r)
91		}
92	
93		// Pass 1: declared funcs/methods + a map from the *types.Func object to its
94		// declaration site, so call resolution can land on an in-module declaration.
95		funcSite := map[*types.Func]Symbol{}
96		nameIndex := map[string][]Symbol{} // name -> declaration sites (for the naive baseline)
97		symSeen := map[string]bool{}
98		compiledSet := map[string]bool{}
99		type fileDecl struct {
100			pkg  *packages.Package
101			decl *ast.FuncDecl
102			sym  Symbol
103		}
104		var callerDecls []fileDecl
105	
106		for _, pkg := range pkgs {
107			out.Stats.LoadErrs += len(pkg.Errors)
108			for _, gf := range pkg.GoFiles {
109				compiledSet[rel(gf)] = true
110			}
111			if pkg.Fset == nil || pkg.TypesInfo == nil {
112				continue
113			}
114			out.Stats.Packages++
115			for _, file := range pkg.Syntax {
116				for _, decl := range file.Decls {
117					fd, ok := decl.(*ast.FuncDecl)
118					if !ok || fd.Name == nil {
119						continue
120					}
121					pos := pkg.Fset.Position(fd.Name.Pos())
122					kind := "function"
123					if fd.Recv != nil {
124						kind = "method"
125					}
126					sym := Symbol{File: rel(pos.Filename), Line: pos.Line, Name: fd.Name.Name, Kind: kind}
127					key := fmt.Sprintf("%s:%d", sym.File, sym.Line)
128					if !symSeen[key] {
129						symSeen[key] = true
130						out.Symbols = append(out.Symbols, sym)
131						nameIndex[sym.Name] = append(nameIndex[sym.Name], sym)
132					}
133					if obj, ok := pkg.TypesInfo.Defs[fd.Name].(*types.Func); ok && obj != nil {
134						funcSite[obj] = sym
135					}
136					if fd.Body != nil {
137						callerDecls = append(callerDecls, fileDecl{pkg: pkg, decl: fd, sym: sym})
138					}
139				}
140			}
141		}
142	
143		// Pass 2: resolve each call expression's callee to a *types.Func and, when it
144		// lands on an in-module declaration, record a caller->callee edge.
145		edgeSeen := map[string]bool{}
146		naiveSeen := map[string]bool{}
147		mkEdge := func(from Symbol, to Symbol) (Edge, string) {
148			e := Edge{
149				FromFile: from.File, FromLine: from.Line, FromName: from.Name,
150				ToFile: to.File, ToLine: to.Line, ToName: to.Name,
151			}
152			return e, fmt.Sprintf("%s:%d->%s:%d", e.FromFile, e.FromLine, e.ToFile, e.ToLine)
153		}
154		for _, cd := range callerDecls {
155			ast.Inspect(cd.decl.Body, func(n ast.Node) bool {
156				call, ok := n.(*ast.CallExpr)
157				if !ok {
158					return true
159				}
160				var id *ast.Ident
161				switch fn := call.Fun.(type) {
162				case *ast.Ident:
163					id = fn
164				case *ast.SelectorExpr:
165					id = fn.Sel
166				}
167				if id == nil {
168					return true
169				}
170				// NAIVE baseline: link the caller to every in-module function sharing
171				// the callee identifier's name, with NO type resolution. This is the
172				// floor a tool gets without scope/type analysis.
173				for _, site := range nameIndex[id.Name] {
174					ne, nk := mkEdge(cd.sym, site)
175					if !naiveSeen[nk] {
176						naiveSeen[nk] = true
177						out.NaiveCalls = append(out.NaiveCalls, ne)
178					}
179				}
180				// TRUTH: type-resolved callee, restricted to in-module declarations.
181				fnObj, ok := cd.pkg.TypesInfo.Uses[id].(*types.Func)
182				if !ok {
183					return true
184				}
185				callee, ok := funcSite[fnObj]
186				if !ok {
187					return true // external / stdlib — out of intra-module scope
188				}
189				e, k := mkEdge(cd.sym, callee)
190				if !edgeSeen[k] {
191					edgeSeen[k] = true
192					out.Calls = append(out.Calls, e)
193				}
194				return true
195			})
196		}
197	
198		sort.Slice(out.Symbols, func(i, j int) bool {
199			if out.Symbols[i].File != out.Symbols[j].File {
200				return out.Symbols[i].File < out.Symbols[j].File
201			}
202			return out.Symbols[i].Line < out.Symbols[j].Line
203		})
204		for f := range compiledSet {
205			out.CompiledFiles = append(out.CompiledFiles, f)
206		}
207		sort.Strings(out.CompiledFiles)
208		out.Stats.Symbols = len(out.Symbols)
209		out.Stats.Calls = len(out.Calls)
210	
211		enc := json.NewEncoder(os.Stdout)
212		enc.SetIndent("", "  ")
213		if err := enc.Encode(out); err != nil {
214			fatal(err)
215		}
216	}
217	
218	func fatal(err error) {
219		fmt.Fprintln(os.Stderr, "oracle:", err)
220		os.Exit(1)
221	}
