export const meta = {
  name: 'audit-agentic-swebench',
  description: 'Adversarial integrity+correctness audit of GraphMark suite 3 (agentic-swebench): does it work, use entire-graph properly, and not cheat',
  phases: [
    { title: 'Find', detail: '8 anti-cheat / correctness finder lenses over the harness' },
    { title: 'Verify', detail: 'independently confirm or refute each finding against the code' },
  ],
}

const GM = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark'
const AS = GM + '/agentic-swebench'
const EG = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/entire-graph'

const FINDINGS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    lens: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: {
          id: { type: 'string', description: 'short kebab slug' },
          title: { type: 'string' },
          category: { type: 'string', enum: ['arm-parity','answer-leak','scoring-integrity','graph-usage','token-accounting','disclosure','test-coverage','doc-accuracy','correctness-bug','reproducibility'] },
          severity: { type: 'string', enum: ['critical','high','medium','low'] },
          file: { type: 'string' }, line: { type: 'integer' },
          evidence: { type: 'string', description: 'what the code ACTUALLY does, quote file:line' },
          why_problem: { type: 'string', description: 'concretely how this enables cheating / breaks correctness / misleads a reader; give the failure scenario' },
          proposed_fix: { type: 'string' },
          confidence: { type: 'string', enum: ['certain','likely','speculative'] },
        },
        required: ['id','title','category','severity','file','evidence','why_problem','proposed_fix','confidence'],
      },
    },
  },
  required: ['lens','findings'],
}

const VERIFY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    id: { type: 'string' },
    verdict: { type: 'string', enum: ['confirmed','refuted','needs-nuance'] },
    evidence: { type: 'string', description: 'the exact code/line you checked; why the claim holds or fails' },
    corrected_severity: { type: 'string', enum: ['critical','high','medium','low','none'] },
    is_real_cheat_or_bug: { type: 'boolean', description: 'true only if it genuinely lets the treated arm win unfairly, breaks the harness, or misstates a fact to a reader' },
    fix_notes: { type: 'string' },
  },
  required: ['id','verdict','evidence','corrected_severity','is_real_cheat_or_bug'],
}

const base = `You are adversarially AUDITING GraphMark's suite 3 = agentic-swebench (${AS}), an A/B benchmark measuring whether giving a coding agent an entire-graph code-graph tool changes how often / how cheaply it resolves real SWE-bench Multilingual issues. The treated arm gets a graph-query tool over a prebuilt entire-graph dump at base_commit; baseline does not; patches are graded by the official swebench Docker harness. The tool under test, entire-graph, is at ${EG}. The whole repo is ${GM}.

Your job: find every way this harness could WORK INCORRECTLY, USE ENTIRE-GRAPH IMPROPERLY, or CHEAT (unfairly advantage the treated arm, leak the answer, grade dishonestly, or misreport results). READ THE ACTUAL FILES named below (open them, quote real line numbers). Be concrete and skeptical; a hunch is fine if you mark confidence:speculative, but evidence must cite real code. Do NOT invent findings to pad the list — a short list of real issues beats a long list of noise. Report via the schema.`

const LENSES = [
  { key: 'arm-parity', prompt: `${base}

