export const meta = {
  name: 'reaudit-agentic-swebench-fixes',
  description: 'Verify each of the 8 confirmed audit fixes is resolved + adversarially sweep the edits for newly-introduced issues',
  phases: [
    { title: 'Confirm-fixes', detail: 'one verifier per confirmed finding: is it actually resolved by the new code?' },
    { title: 'New-issue sweep', detail: 'hunt for regressions / new inconsistencies / over-claims introduced by the edits' },
  ],
}

const AS = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench'
const EG = '/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/entire-graph'

const FIX_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    id: { type: 'string' },
    resolved: { type: 'boolean' },
    evidence: { type: 'string', description: 'the exact post-edit code/prose you read that resolves (or fails to resolve) it' },
    residual: { type: 'string', description: 'any remaining gap, or empty if fully resolved' },
  },
  required: ['id', 'resolved', 'evidence'],
}

const SWEEP_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    new_issues: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: {
          title: { type: 'string' },
          severity: { type: 'string', enum: ['critical','high','medium','low'] },
          file: { type: 'string' }, line: { type: 'integer' },
          problem: { type: 'string' }, fix: { type: 'string' },
          confidence: { type: 'string', enum: ['certain','likely','speculative'] },
        },
        required: ['title','severity','file','problem','fix','confidence'],
      },
    },
  },
  required: ['new_issues'],
}

const FIXES = [
  { id: 'v2-clean-eval-never-produced', check: `run_eval_model.sh now takes an optional [raw|clean|v2] 3rd arg mapping to preds{,_clean,_v2}.json + a matching run_id suffix; README reproduce step passes 'raw' for both arms. Verify the advertised v2 path is now actually runnable and both-arms-same-variant is documented.`, files: `${AS}/tools/run_eval_model.sh, ${AS}/README.md` },
  { id: 'score-header-hardcodes-v2', check: `score_matrix.py must derive the methodology line (out[1]) from the eval suffix ACTUALLY scored (cats_used) instead of hardcoding '(v2)'. Verify for the raw case it now says 'raw, uncleaned patches', and it compiles.`, files: `${AS}/tools/score_matrix.py` },
  { id: 'calls-not-fixed-062-filter', check: `filter_edges.py comments must no longer claim a FIXED/uniform 0.62 confidence (should describe the graded cascade), AND CAP_IN must keep each target's highest-confidence callers (not first-by-from_id). Verify the new CAP_IN loop groups by target and keeps top-CAP_IN by keeprank, stays deterministic + bounded, and the new test test_filter_edges_confidence.py pins it.`, files: `${AS}/tools/filter_edges.py, ${AS}/tests/test_filter_edges_confidence.py` },
  { id: 'cache-read-backwards', check: `fair_tokens.py + score_matrix.py prose must now state the CORRECT direction: excluding cache_read (real) is the MORE treated-favorable metric; total/$ are the conservative checks. Verify no remaining text claims excluding cache_read is the conservative/fair choice.`, files: `${AS}/tools/fair_tokens.py, ${AS}/tools/score_matrix.py` },
  { id: 'capped-runs-undisclosed', check: `score_matrix.py + fair_tokens.py must detect subtype=='error_max_turns' and disclose per-arm capped counts. Verify the detection field + the disclosure output exist and are correct.`, files: `${AS}/tools/score_matrix.py, ${AS}/tools/fair_tokens.py` },
  { id: 'readme-pending-but-committed', check: `README 'Current results' + results/.gitkeep must no longer say 'pending/discarded/nothing trustworthy' while a full report is committed; they should describe the retained sonnet pilot honestly (raw eval, 27/30 tie, caveats) and note the official clean run is still pending. Verify consistency with the committed results/matrix_compare.md.`, files: `${AS}/README.md, ${AS}/results/.gitkeep, ${AS}/results/matrix_compare.md` },
  { id: 'prose-v2-but-raw', check: `results/matrix_compare.md line 3 prose must now say 'raw' (matching its own per-model 'eval suffix raw' header), not '(v2)'.`, files: `${AS}/results/matrix_compare.md` },
  { id: 'readme-calls-062-false', check: `README limitations must replace 'fixed-confidence (0.62)' with the real graded cascade (0.92/0.86/0.80/0.68-0.64/0.55-0.62). Cross-check the cascade values are plausible vs the tool at ${EG} (internal/sem/provider.go).`, files: `${AS}/README.md, ${EG}` },
