phase('New-issue sweep')
const SWEEPS = [
  { key: 'code-regressions', prompt: `Adversarially review the EDITED harness code for NEW bugs the audit fixes may have introduced. Read ${AS}/tools/filter_edges.py (esp. the rewritten CAP_IN loop — does grouping by target then keeping top-CAP_IN preserve determinism, boundedness, and not drop MORE than before or change non-CALLS handling? any edge case with dedup, missing to_id, or the kept_lines.sort()?), ${AS}/tools/score_matrix.py (the deferred out[1] methodology line — is out[1] always set before write even when no model has eval / cats_used empty? does the capped-disclosure loop crash on missing stats?), ${AS}/tools/fair_tokens.py, ${AS}/tools/run_eval_model.sh (variant case-stmt correctness). Report only REAL new problems.` },
  { key: 'doc-overclaim', prompt: `Adversarially review the EDITED prose for NEW inaccuracies or over-claims I introduced. Read ${AS}/README.md, ${AS}/results/.gitkeep, ${AS}/results/matrix_compare.md. Check: does the new 'Current results' section over-claim provenance it can't support (e.g. asserting the committed pilot is post-audit-fix when that isn't established)? Is the '27/30 tie / 90%' consistent with matrix_compare.md's actual table? Is the CALLS cascade description (0.92/0.86/0.80/0.68-0.64/0.55-0.62) internally consistent between README and filter_edges.py? Any remaining contradiction between README/.gitkeep and the committed results? Report only real issues.` },
  { key: 'behavioral-fidelity', prompt: `The CAP_IN fix in ${AS}/tools/filter_edges.py changes which CALLS edges survive (now confidence-preferring both directions). Assess whether this could HARM the benchmark's fairness or the graphs' validity: does keeping higher-confidence calls over lower-confidence ones bias the treated arm unfairly, or is it strictly a fidelity improvement (keeping resolved calls over name-collision noise)? Could it violate the <200MB bound or the completeness-validation contract in ${AS}/tools/graph_stats.py / build_graph.sh? Is the new behavior still disclosed accurately in README? Report any concern.` },
]
const sweeps = await parallel(SWEEPS.map((s) => () =>
  agent(s.prompt, { label: `sweep:${s.key}`, phase: 'New-issue sweep', schema: SWEEP_SCHEMA, effort: 'high' })
    .then((v) => ({ key: s.key, new_issues: (v && v.new_issues) || [] }))
))

const unresolved = fixResults.filter((f) => f && !f.resolved)
const newIssues = sweeps.flatMap((s) => (s.new_issues || []).map((i) => ({ ...i, sweep: s.key })))
return { fixResults, unresolved_count: unresolved.length, unresolved, new_issues_count: newIssues.length, new_issues: newIssues }

