def _print_syms(syms, source=False):
    if not syms:
        print("(none)")
        return
    for i, s in enumerate(syms[:CAP]):
        print(_sym_short(s))
        if source and i < SOURCE_CAP:      # dump source only for the top few matches
            snip = _snippet(s)
            if snip:
                print(snip.rstrip("\n"))
                print()
    if source and len(syms) > SOURCE_CAP:
        print(f"(source shown for the first {SOURCE_CAP} of {len(syms)} matches; "
              f"pass a more specific name or file:line to view another)")
    if len(syms) > CAP:
        print(f"... (+{len(syms)-CAP} more; narrow the query)")


def _match_symbols(syms, pat):
    """General symbol match: regex (if it compiles) OR plain substring, whichever hits — so a
    query with regex metachars OR a bare substring both work. Results are relevance-ranked
    exact-name > case-insensitive-exact > prefix > other, so a common word (`format`) surfaces
    the real symbol first instead of hundreds of template/instantiation rows."""
    lit = pat.lower()
    try:
        rx = re.compile(pat)
    except re.error:
        rx = None

    def hit(s):
        name = s.get("name", "") or ""
        q = s.get("qualified_name", "") or ""
        if rx is not None and (rx.search(name) or rx.search(q)):
            return True
        return lit in (name + " " + q).lower()

    def rank(s):
        name = s.get("name", "") or ""
        if name == pat:
            return 0
        if name.lower() == lit:
            return 1
        if name.lower().startswith(lit):
            return 2
        return 3

    hits = [s for s in syms if hit(s)]
    hits.sort(key=rank)   # stable: preserves file order within a tier
    return hits


def _resolve(syms, arg):
    """Resolve a symbol reference for def/show/callers/callees. Accepts a bare name /
    qualified_name, OR a `path:line` location -> the smallest symbol enclosing that line in a
    file whose path contains `path`. The file:line form is what agents actually type when they
    already have a stack/grep location; matching it kills the `def <file:line>` -> (none) case
    that forced a redundant Read."""
    hits = [s for s in syms if s.get("name") == arg or s.get("qualified_name") == arg]
    if hits:
        return hits
    path, sep, ln = arg.rpartition(":")
    if sep and path and ln.isdigit():
        L = int(ln)
        cand = [s for s in syms
                if path in (s.get("file_path", "") or "")
                and (s.get("start_line") or 0) <= L <= (s.get("end_line") or s.get("start_line") or 0)]
        # smallest enclosing span first (the precise symbol, not its container)
        cand.sort(key=lambda s: (s.get("end_line", 0) or 0) - (s.get("start_line", 0) or 0))
        return cand
    return []

