package sem

import "testing"

func TestCompletenessLevel(t *testing.T) {
	cases := []struct {
		name                            string
		failures, files, parsed, symbol int
		want                            string
	}{
		{"empty scope", 0, 0, 0, 0, "ok"},
		{"clean full parse", 0, 100, 100, 4000, "ok"},
		// The subdir/mis-scope bug: a stray config file parses fine (no failure)
		// but the real source was never discovered. Must NOT report "ok".
		{"parsed but no symbols", 0, 3, 3, 0, "degraded"},
		{"majority unparsed", 0, 100, 30, 500, "unsafe"},
		{"a few hard failures", 2, 100, 98, 4000, "degraded"},
		{"mostly failures", 30, 100, 70, 500, "unsafe"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := completenessLevel(tc.failures, tc.files, tc.parsed, tc.symbol)
			if got != tc.want {
				t.Fatalf("completenessLevel(f=%d files=%d parsed=%d sym=%d) = %q, want %q",
					tc.failures, tc.files, tc.parsed, tc.symbol, got, tc.want)
			}
		})
	}
}

package cli

import (
	"strings"
	"testing"

	"github.com/entireio/entire-graph/internal/sem"
)

func TestIDMatches(t *testing.T) {
	const id = "gh/apache/druid:Bash:distribution/docker/peon.sh:function:getConfPath"
	cases := []struct {
		sel  string
		want bool
	}{
		{id, true},                      // exact full ID
		{"getConfPath", true},           // trailing name segment
		{"function:getConfPath", true},  // kind:name tail
		{"getConf", false},              // partial word must not match
		{"peon.sh:function:getConfPath", true},
		{"otherName", false},
	}
	for _, tc := range cases {
		if got := idMatches(id, tc.sel); got != tc.want {
			t.Errorf("idMatches(id, %q) = %v, want %v", tc.sel, got, tc.want)
		}
	}
}

func TestRelationMatches(t *testing.T) {
	rel := sem.RelationRecord{
		FromID: "gh/o/r:Go:a.go:function:Caller",
		ToID:   "gh/o/r:Go:b.go:function:Callee",
		Type:   "CALLS",
	}
	mk := func(to, from string, relTypes ...string) providerFlags {
		return providerFlags{To: to, From: from, Relation: relTypes}
	}
	if !relationMatches(rel, mk("Callee", "", "CALLS")) {
		t.Error("expected match on to=Callee relation=CALLS")
	}
	if !relationMatches(rel, mk("Callee", "", "REFERENCES", "CALLS")) {
		t.Error("expected match when CALLS is one of several relation types")
	}
	if relationMatches(rel, mk("Callee", "", "REFERENCES")) {
		t.Error("must not match when relation type differs")
	}
	if relationMatches(rel, mk("Nope", "", "CALLS")) {
		t.Error("must not match when --to selector misses")
	}
	if !relationMatches(rel, mk("", "Caller")) {
		t.Error("expected match on from=Caller with no relation constraint")
	}
	if !relationMatches(rel, providerFlags{}) {
		t.Error("empty filter should match any edge")
	}
}

func TestWarnIfPartial(t *testing.T) {
	ok := &sem.SnapshotSummary{Stats: sem.ProviderStats{CompletenessLevel: "ok", Files: 10, ParsedFiles: 10}}
	var b strings.Builder
	warnIfPartial(&b, false, ok)
	if b.Len() != 0 {
		t.Errorf("clean run must be silent, got: %q", b.String())
	}

	// The subdir bug: 1 stray file, no --worktree → loud warning naming --worktree.
	subdir := &sem.SnapshotSummary{Stats: sem.ProviderStats{CompletenessLevel: "degraded", Files: 1, ParsedFiles: 1, Symbols: 0}}
	b.Reset()
	warnIfPartial(&b, false, subdir)
	out := b.String()
	if !strings.Contains(out, "DEGRADED") || !strings.Contains(out, "--worktree") {
		t.Errorf("subdir partial parse must warn loudly + suggest --worktree, got: %q", out)
	}

	// nil summary (stream produced none) must not panic.
	b.Reset()
	warnIfPartial(&b, false, nil)
}

#!/usr/bin/env python3
"""2x graph-vs-no-graph token report.
treated = mean(real tokens over sonnet_s1, sonnet_s2); baseline = mean(sonnet_bl1, sonnet_bl2).
"real" tokens = cache_creation + input + output (excludes cache_read). Only counts a run that
actually produced a paid result (total_cost_usd>0). Reports per-repo delta + aggregates +
search-first hit rate. NO cherry-picking: every present run is averaged."""
import json, os, glob, statistics as st

AS = "/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench"
TREATED = ["sonnet_s1", "sonnet_s2"]
BASELINE = ["sonnet_bl1", "sonnet_bl2"]

def real(path):
    if not os.path.exists(path):
        return None
    try:
        d = json.load(open(path))
    except Exception:
        return None
    if (d.get("total_cost_usd", 0) or 0) <= 0:
        return None
    u = d.get("usage", {}) or {}
    return (u.get("cache_creation_input_tokens", 0) or 0) + (u.get("input_tokens", 0) or 0) + (u.get("output_tokens", 0) or 0)

def arm_runs(tag, arm):
    return {os.path.basename(os.path.dirname(p)): p
            for p in glob.glob(f"{AS}/results/{tag}/{arm}/*/cc_out.json")}

def searched_first(tag, iid):
    log = f"{AS}/results/{tag}/treated/{iid}/gq_calls.log"
    if not os.path.exists(log):
        return None
    first = (open(log).read().strip().split("\n") or [""])[0]
    return first.startswith("search")

# collect union of iids
t_runs = {tag: arm_runs(tag, "treated") for tag in TREATED}
b_runs = {tag: arm_runs(tag, "baseline") for tag in BASELINE}
iids = set()
for m in list(t_runs.values()) + list(b_runs.values()):
    iids |= set(m)

rows, deltas, tot_t, tot_b, hits, hit_den = [], [], 0, 0, 0, 0
for iid in sorted(iids):
    tv = [real(t_runs[tag][iid]) for tag in TREATED if iid in t_runs[tag]]
    tv = [x for x in tv if x is not None]
    bv = [real(b_runs[tag][iid]) for tag in BASELINE if iid in b_runs[tag]]
    bv = [x for x in bv if x is not None]
    if not tv or not bv:
        rows.append((iid, tv, bv, None, None))
        continue
    tm, bm = st.mean(tv), st.mean(bv)
    d = (tm - bm) / bm * 100
    rows.append((iid, tv, bv, tm, d))
    deltas.append(d); tot_t += tm; tot_b += bm
    sf = searched_first(TREATED[0], iid)
    if sf is not None:
        hit_den += 1; hits += 1 if sf else 0

print(f"{'repo':<34}{'t_runs':>16}{'b_runs':>16}{'Δ%':>8}")
print("-" * 74)
for iid, tv, bv, tm, d in rows:
    ts = ",".join(f"{x//1000}k" for x in tv) or "-"
    bs = ",".join(f"{x//1000}k" for x in bv) or "-"
    ds = f"{d:+.0f}%" if d is not None else "(incomplete)"
    print(f"{iid[:34]:<34}{ts:>16}{bs:>16}{ds:>8}")
print("-" * 74)
if deltas:
    complete = len([r for r in rows if r[4] is not None])
    winners = len([d for d in deltas if d < 0])
    print(f"pairs complete: {complete}/{len(rows)}   graph-wins (Δ<0): {winners}/{len(deltas)}")
    print(f"MEAN per-repo Δ:        {st.mean(deltas):+.1f}%   (median {st.median(deltas):+.1f}%)")
    print(f"TOKEN-WEIGHTED Δ total: {(tot_t-tot_b)/tot_b*100:+.1f}%   (treated {tot_t/1000:.0f}k vs baseline {tot_b/1000:.0f}k)")
    if hit_den:
        print(f"search-first hit rate:  {hits}/{hit_den} ({hits/hit_den*100:.0f}%) of treated run-1 tasks called search FIRST")
else:
    print("no complete pairs yet")

