#!/usr/bin/env python3
"""Graph-vs-no-graph report on ALL metrics (never hide cache_read again).
Usage: measure_all.py <treated_tag1,treated_tag2,...> <baseline_tag1,...>
Averages each iid across the treated tags and across the baseline tags, then reports
weighted + mean deltas for: total tokens (cc+in+out+cache_read, = 'tokens spent'),
cost ($), and 'real' (cc+in+out, excludes cache_read). Only paid runs counted."""
import json, glob, os, sys, statistics as st

AS = "/private/tmp/claude-501/-Users-suhaan-devenv/7e3deab1-a028-46d5-9bf1-3318de93a0b6/scratchpad/graphmark/agentic-swebench"
TREATED = (sys.argv[1] if len(sys.argv) > 1 else "tg1,tg2").split(",")
BASELINE = (sys.argv[2] if len(sys.argv) > 2 else "db1,db2").split(",")
TARM = sys.argv[3] if len(sys.argv) > 3 else "treated"
BARM = sys.argv[4] if len(sys.argv) > 4 else "baseline"

def u(p):
    try: d = json.load(open(p))
    except Exception: return None
    if (d.get("total_cost_usd", 0) or 0) <= 0: return None
    x = d.get("usage", {}) or {}
    cc = x.get("cache_creation_input_tokens", 0) or 0
    inp = x.get("input_tokens", 0) or 0
    out = x.get("output_tokens", 0) or 0
    cr = x.get("cache_read_input_tokens", 0) or 0
    return dict(total=cc+inp+out+cr, real=cc+inp+out, cost=d.get("total_cost_usd", 0))

def collect(tags, arm):
    per = {}
    for tag in tags:
        for p in glob.glob(f"{AS}/results/{tag}/{arm}/*/cc_out.json"):
            iid = os.path.basename(os.path.dirname(p)); m = u(p)
            if m: per.setdefault(iid, []).append(m)
    return {i: {k: st.mean(r[k] for r in v) for k in ("total","real","cost")} for i, v in per.items()}

T = collect(TREATED, TARM); B = collect(BASELINE, BARM)
ids = sorted(i for i in set(T) & set(B))
print(f"treated={TREATED} baseline={BASELINE}  ({len(ids)} repos paired)\n")
print(f"{'repo':<26}{'total Δ':>9}{'cost Δ':>9}{'real Δ':>9}")
for i in ids:
    r = {k: (T[i][k]-B[i][k])/B[i][k]*100 if B[i][k] else 0 for k in ("total","cost","real")}
    print(f"{i.split('__')[0][:26]:<26}{r['total']:>+8.0f}%{r['cost']:>+8.0f}%{r['real']:>+8.0f}%")
print("-"*53)
for key in ("total", "cost", "real"):
    t = sum(T[i][key] for i in ids); b = sum(B[i][key] for i in ids)
    ds = [(T[i][key]-B[i][key])/B[i][key]*100 for i in ids if B[i][key]]
    print(f"{key:<6} weighted {(t-b)/b*100:+6.1f}%   mean {st.mean(ds):+6.1f}%   graph-wins {sum(1 for d in ds if d<0)}/{len(ds)}")

