		// function split into MaxRegionLines sub-regions still expands to its real
		// body rather than one arbitrary sub-window.
		if symbol, ok := symbolsByID[results[i].SymbolID]; ok && symbol.StartLine > 0 && symbol.EndLine >= symbol.StartLine {
			start, end = symbol.StartLine, symbol.EndLine
		}
		if start <= 0 || end < start || end-start+1 > searchFullBodyMaxLines {
			continue // ranks are independent; a huge #1 does not block #2
		}
		content, ok := read(results[i].FilePath)
		if !ok {
			continue
		}
		fileLines := strings.Split(content, "\n")
		cs, ce := clampRegion(start, end, len(fileLines))
		if cs == 0 {
			continue
		}
		key := fmt.Sprintf("%s\x00%d:%d", results[i].FilePath, cs, ce)
		if seen[key] {
			continue // another top hit already emitted this exact function body
		}
		candidate := results[i]
		candidate.Snippet = strings.Join(fileLines[cs-1:ce], "\n")
		candidate.SnippetStartLine = cs
		candidate.SnippetEndLine = ce
		size := serializedSearchResultBytes(candidate)
		if size > searchFullBodyMaxBytes {
			continue // body too large; keep the focused snippet
		}
		if combinedCap > 0 && combinedUsed+size > combinedCap {
			continue // aggregate widened-body cap reached
		}
		results[i] = candidate
		protected[i] = true
		seen[key] = true
		combinedUsed += size
	}
	return protected
}

func fitSearchResultsToBudget(results []SearchResult, q searchQuery, budget int) ([]SearchResult, int, int, int) {
	return fitSearchResultsToBudgetProtecting(results, q, budget, nil)
}

// fitSearchResultsToBudgetProtecting is fitSearchResultsToBudget with a protected
// mask: results whose position is marked are kept verbatim (never compacted), so
// widened full bodies survive; unprotected results share the remaining budget and
// the tail is dropped/compacted first, exactly as before when protected is nil.
func fitSearchResultsToBudgetProtecting(results []SearchResult, q searchQuery, budget int, protected []bool) ([]SearchResult, int, int, int) {
	originalCount := len(results)
	if budget <= 0 || len(results) == 0 {
		return results, serializedSearchResultBytes(results), 0, 0
	}
	isProtected := func(i int) bool { return protected != nil && i < len(protected) && protected[i] }

	for count := len(results); count > 0; count-- {
		protectedBytes, unprotected := 0, 0
		for index := 0; index < count; index++ {
			if isProtected(index) {
				protectedBytes += serializedSearchResultBytes(results[index])
			} else {
				unprotected++
			}
		}
		perResult := 256
		if unprotected > 0 {
			perResult = maxInt(256, (budget-2-protectedBytes-(unprotected-1))/unprotected)
		}
		compacted := make([]SearchResult, count)
		truncated := 0
		for index := range compacted {
			if isProtected(index) {
				compacted[index] = results[index] // keep the full widened body verbatim
				continue
			}
			compacted[index], _ = compactSearchResultToBytes(results[index], q, perResult)
			if compacted[index].Snippet != results[index].Snippet || compacted[index].Signature != results[index].Signature {
				truncated++
			}
		}
		resultBytes := serializedSearchResultBytes(compacted)
		if resultBytes <= budget {
			return compacted, resultBytes, originalCount - count, truncated
		}
	}
	return []SearchResult{}, serializedSearchResultBytes([]SearchResult{}), originalCount, 0
}

