#!/usr/bin/env python3
"""Sum token usage from a pi --mode json event stream (pi_out.jsonl).

Each assistant API call emits exactly one message_end event whose message carries that
call's usage; summing over assistant message_end events = session total. Emits JSON:
{"total": t, "input": i, "output": o, "cache_read": r, "cache_write": w, "cost": c,
 "assistant_msgs": n, "settled": bool}
"""
import json, sys

path = sys.argv[1]
tot = {"input": 0, "output": 0, "cache_read": 0, "cache_write": 0, "cost": 0.0}
n = 0
settled = False
for line in open(path, errors="replace"):
    line = line.strip()
    if not line or not line.startswith("{"):
        continue
    try:
        d = json.loads(line)
    except Exception:
        continue
    t = d.get("type")
    if t == "agent_settled":
        settled = True
    if t != "message_end":
        continue
    m = d.get("message") or {}
    if m.get("role") != "assistant":
        continue
    u = m.get("usage") or {}
    tot["input"] += u.get("input", 0) or 0
    tot["output"] += u.get("output", 0) or 0
    tot["cache_read"] += u.get("cacheRead", 0) or 0
    tot["cache_write"] += u.get("cacheWrite", 0) or 0
    tot["cost"] += ((u.get("cost") or {}).get("total", 0) or 0)
    n += 1
out = {
    "total": tot["input"] + tot["output"] + tot["cache_read"] + tot["cache_write"],
    **tot, "assistant_msgs": n, "settled": settled,
}
print(json.dumps(out))

