package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra"
)

// agentGuideDoc is the operating guide installed into a consuming project by
// `entire brain init-agents`. It is written AS INSTRUCTIONS TO THE AGENT that
// reads it (via AGENTS.md / CLAUDE.md), not as documentation about the plugin:
// a live agent skims prose but follows imperatives. It covers the brain and the
// code graph together, because they answer different halves of the same
// question — the graph knows the code as it is now, the brain remembers why it
// got that way and what was already tried.
const agentGuideDoc = `# entire brain + graph — instructions for coding agents (follow directly)

This repo has a local repository **brain** (durable facts, past sessions, decisions,
docs, semantic index) and a deterministic **code graph** (symbols, calls, types).
Both are local, no network. These instructions are FOR YOU, the agent reading this
file. Following them replaces most grep/read exploration — measured to cut agent
token usage roughly in half.

## Start every non-trivial task with ONE brief

    entire brain brief "<the task in one sentence>" --json

That single call returns: freshness + live git state, the likely files and symbols,
the tests that cover them, matching past decisions, and the durable facts for this
task. Read it before touching the filesystem. It is the entry point — not status,
not search.

## Then, by question type — one call, not a tour

    "where is / what code does X"      entire graph search --repo . --profile full --query "X"
    "what breaks if I change X"        entire graph impact --repo . --symbol X
    "was this decided/tried before"    entire brain recall "<topic>" --json
    "find anything about <topic>"      entire brain query "<topic>" --json      (hybrid: keyword+concept)
    "exact identifier, no paraphrase"  entire brain search "<identifier>" --json
    "what is this project"             entire brain overview --json             (once, when new to the repo)
    "full record behind a result"      entire brain get <id> --json             (ids come from any result)

## Hard rules

1. BRIEF FIRST on real tasks; GRAPH SEARCH FIRST when you only need to locate code.
   Never grep/find/cat to explore before one of those.
2. ONE call, then act. Do not chain retrieval commands to "explore" — that is the
   single biggest token waste. If the first call missed, ask a sharper question once.
3. Read line ranges (~120 lines max), never whole files. Results carry file:line.
4. Trust the results. They are deterministic/provenance-anchored; do not re-verify
   with a second tool before editing.
5. Every extra turn re-reads your whole context — that is the token cost. Reach the
   edit in as few turns as possible and stop when you can justify the fix.
6. Check ` + "`freshness`" + ` in brief/status output. If it says stale, say so in your
   answer rather than silently trusting old context.
7. When you learn something durable that the brain did not know (a non-obvious
   constraint, a why), record it:  entire brain remember "<fact>" --json

## When NOT to use them

The task already names the exact small file, or the repo is tiny: just read it. These
tools save tokens by removing exploration — when there is nothing to explore, skip them.

## Reference

    task packet   ->  entire brain brief "<task>" --json
    prior art     ->  entire brain recall "<topic>" --json | entire brain query "<q>" --json
    locate code   ->  entire graph search --repo . --profile full --query "..."
    blast radius  ->  entire graph impact --repo . --symbol X
    callers only  ->  entire graph neighbors --repo . --symbol X --relation CALLS --direction in
    what changed  ->  entire graph diff --base A --head B --json
    deeper brain  ->  entire brain guide   (full command surface, incl. inspect/*)
`

const (
	agentPointerBegin = "<!-- entire-brain:begin -->"
	agentPointerEnd   = "<!-- entire-brain:end -->"
)

func newInitAgentsCommand() *cobra.Command {
	var repo string
	cmd := &cobra.Command{
		Use:   "init-agents",
		Short: "Install the brain+graph agent guide into a project's AGENTS.md and CLAUDE.md",
		Long: strings.TrimSpace(`
Writes .entire/brain-agent.md (the agent operating guide for the brain and the code
graph) into the target project and adds a small marker-guarded pointer block to
AGENTS.md (the cross-agent convention) and CLAUDE.md (with an @-import line), so any
coding agent working in that project picks up the doctrine automatically.

Re-running updates the block in place; existing content is never overwritten.`),
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			root, err := filepath.Abs(repo)
			if err != nil {
				return err
			}
			if info, statErr := os.Stat(root); statErr != nil || !info.IsDir() {
				return fmt.Errorf("init-agents: %s is not a directory", root)
			}

			guidePath := filepath.Join(root, ".entire", "brain-agent.md")
			if err := os.MkdirAll(filepath.Dir(guidePath), 0o755); err != nil {
				return err
			}
			if err := os.WriteFile(guidePath, []byte(agentGuideDoc), 0o644); err != nil {
				return err
			}
			fmt.Fprintf(cmd.OutOrStdout(), "wrote %s\n", guidePath)

			pointer := agentPointerBegin + "\n" +
				"This repo has an Entire brain (durable facts, past decisions, sessions) and a\n" +
				"local code graph. Before exploring with grep/find/whole-file reads, read\n" +
				".entire/brain-agent.md — start tasks with `entire brain brief \"<task>\"`.\n" +
				"@.entire/brain-agent.md\n" +
				agentPointerEnd + "\n"

			for _, name := range []string{"AGENTS.md", "CLAUDE.md"} {
				path := filepath.Join(root, name)
				if err := upsertAgentPointer(path, pointer); err != nil {
					return fmt.Errorf("init-agents: %s: %w", name, err)
				}
				fmt.Fprintf(cmd.OutOrStdout(), "updated %s\n", path)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&repo, "repo", ".", "project root to install the agent guide into")
	return cmd
}

// upsertAgentPointer appends the block, or replaces an existing marker-delimited
// block in place, so repeated runs never duplicate content.
func upsertAgentPointer(path, block string) error {
	existing, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	content := string(existing)
	begin := strings.Index(content, agentPointerBegin)
	end := strings.Index(content, agentPointerEnd)
	switch {
	case begin >= 0 && end > begin:
		content = content[:begin] + strings.TrimSuffix(block, "\n") + content[end+len(agentPointerEnd):]
	case len(content) == 0:
		content = block
	default:
		if !strings.HasSuffix(content, "\n") {
			content += "\n"
		}
		content += "\n" + block
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestInitAgentsInstallsGuideAndIsIdempotent(t *testing.T) {
	repo := t.TempDir()
	if err := os.WriteFile(filepath.Join(repo, "AGENTS.md"), []byte("# project rules\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	run := func() {
		t.Helper()
		cmd := newInitAgentsCommand()
		cmd.SetOut(os.Stdout)
		cmd.SetArgs([]string{"--repo", repo})
		if err := cmd.Execute(); err != nil {
			t.Fatal(err)
		}
	}
	run()

	guide, err := os.ReadFile(filepath.Join(repo, ".entire", "brain-agent.md"))
	if err != nil {
		t.Fatalf("guide not written: %v", err)
	}
	for _, want := range []string{"entire brain brief", "entire graph search", "entire brain recall", "Hard rules"} {
		if !strings.Contains(string(guide), want) {
			t.Fatalf("guide missing %q:\n%s", want, guide)
		}
	}

	agents, err := os.ReadFile(filepath.Join(repo, "AGENTS.md"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(agents), "# project rules") {
		t.Fatalf("existing AGENTS.md content clobbered:\n%s", agents)
	}
	if !strings.Contains(string(agents), agentPointerBegin) {
		t.Fatalf("pointer block missing:\n%s", agents)
	}

	claude, err := os.ReadFile(filepath.Join(repo, "CLAUDE.md"))
	if err != nil {
		t.Fatalf("CLAUDE.md not created: %v", err)
	}
	if !strings.Contains(string(claude), "@.entire/brain-agent.md") {
		t.Fatalf("CLAUDE.md missing import line:\n%s", claude)
	}

	run() // idempotence
	for _, name := range []string{"AGENTS.md", "CLAUDE.md"} {
		b, _ := os.ReadFile(filepath.Join(repo, name))
		if got := strings.Count(string(b), agentPointerBegin); got != 1 {
			t.Fatalf("%s block duplicated (%d):\n%s", name, got, b)
		}
	}
}

